import random

def get_graph():
    V = 25
    for attempt in range(1000):
        adj = {i: set() for i in range(V)}
        edges = []

        def bfs_dist(u, v, limit):
            # return True if distance between u and v is <= limit
            if u == v: return True
            q = [u]
            dist = {u: 0}
            while q:
                curr = q.pop(0)
                if dist[curr] == limit:
                    continue
                for nxt in adj[curr]:
                    if nxt == v:
                        return True
                    if nxt not in dist:
                        dist[nxt] = dist[curr] + 1
                        q.append(nxt)
            return False

        possible_edges = [(i, j) for i in range(V) for j in range(i+1, V)]
        random.shuffle(possible_edges)

        for u, v in possible_edges:
            # If we add edge (u, v), it creates a cycle of length k if dist(u, v) == k-1
            # We want girth >= 7, so we cannot add edge if dist(u, v) <= 5
            if not bfs_dist(u, v, 5):
                adj[u].add(v)
                adj[v].add(u)
                edges.append((u, v))
                if len(edges) == 34:
                    return edges
    return None

edges = get_graph()
